function parseCount(value) {
  if (typeof value !== "string") return null;
  const trimmed = value.trim();
  if (!/^\d+$/.test(trimmed)) return null;
  const n = Number(trimmed);
  if (!Number.isSafeInteger(n) || n < 0) return null;
  return n;
}

console.assert(parseCount(" 42 ") === 42);
console.assert(parseCount("007") === 7);
console.assert(parseCount("1.0") === null);
console.assert(parseCount("-1") === null);
console.assert(parseCount("") === null);
console.assert(parseCount(true) === null);
console.assert(parseCount("99999999999999999999") === null);
```

This uses a strict regex to ensure only ASCII digits remain after trimming. It then validates the numeric result against the safe integer range.
